    '開いているコンピューターはリアルタイムで更新されます。他のコンピューターの確認頻度を下げると、ネットワークの使用量が減ります。アプリがバックグラウンドにある間は接続が一時停止します。通知とLive Activitiesは「通知」で管理します。無効にしたウィジェットには最後に保存されたスナップショットが表示されます。',
