    'ランタイムホストで公式インストーラーを実行し、ステータスを更新してください。CuaDriverをダウンロードしてインストールします。Cuaアカウントは不要です。',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    '最小構成のLinuxシステムにはlibxi6とat-spi2-coreが必要です。GNOMEにはCuaに同梱のWinRectsヘルパーが必要です。インストールガイドを参照してください。',
  'Install and set up Cua Driver': 'Cua Driverをインストールして設定',
  'Detect / check Cua Driver': 'Cua Driverを検出 / 確認',
  '2. Permissions & desktop access': '2. アクセス許可とデスクトップアクセス',
  '3. Agent MCP, skills & hooks': '3. エージェントのMCP、スキル、フック',
  '4. Computer History (optional preview)': '4. Computer History（オプションのプレビュー）',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'macOSのアクセシビリティと画面収録をCuaDriverに許可し、再起動を承認してください。デスクトップアクセスのテストでは、アプリの一覧を表示しますが、変更は行いません。デーモンの操作は、アクティブなコンピュータ操作セッションに影響します。',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'コンピュータ操作の切り替えを保存すると、新しい書き込み可能なターンでdovo_cua MCPが自動的に有効になります。手動でのMCP登録は不要です。オプションの公式スキルパックをインストールすると、このコンピュータで検出されたエージェントが登録されます。',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'オプトイン方式の暗号化されたメタデータのみの履歴です。有効にするとデーモンが再起動する場合があります。無効にしても記録済みデータは保持されます。一時停止すると記録が一時的に停止します。未対応のビルドではエラーが表示されます。データはランタイムホストに保存されます。「最近の履歴を表示」では、ここに最大20件のイベントを取得します。',
  'Delete recorded Computer History?': '記録したComputer Historyを削除しますか？',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'このコンピュータに記録されたすべての履歴と暗号化キーを削除します。この操作は元に戻せません。',
