  'Use custom TURN': 'カスタムTURNを使用',
  'Use automatic relay': '自動リレーを使用',
  'Relay fallback': 'リレーのフォールバック',
  'The computer must allow relay in its pairing QR. For a Direct-only pairing, generate a new Dovo-enabled QR on the computer and pair again.':
    'コンピューター側でペアリング用QRコードのリレーを許可する必要があります。Directのみのペアリングの場合は、コンピューターでDovo対応の新しいQRコードを生成し、再度ペアリングしてください。',
  'Scan pairing QR code': 'ペアリング用QRコードをスキャン',
